import { render } from '@testing-library/react';
import { format } from 'date-fns';

import { subscriptionMock, upcomingSubscriptionMock } from '@proton/testing/data';

import { ExpirationTime as B2BExpirationTime } from './b2bCommonConfig';
import { ExpirationTime as B2CExpirationTime } from './b2cCommonConfig';

const subscription = {
    ...subscriptionMock,
    UpcomingSubscription: {
        ...upcomingSubscriptionMock,
        PeriodEnd: subscriptionMock.PeriodEnd + 86400 * 365,
    },
};

it.each([
    ['consumer', <B2CExpirationTime subscription={subscription} cancellablePlan />],
    ['business', <B2BExpirationTime subscription={subscription} isChargeBeeUser />],
])('shows the active term expiry in the %s cancellation confirmation', (_, component) => {
    const { container } = render(component);
    const time = container.querySelector('time');
    expect(time).toHaveAttribute('dateTime', format(subscriptionMock.PeriodEnd * 1000, 'yyyy-MM-dd'));
    expect(time).toHaveTextContent(format(subscriptionMock.PeriodEnd * 1000, 'PP'));
});

